{{-- Carlito, metric-compatible with the Calibri of the source forms (D-075), from resources/views/pdf/fonts (SIL Open Font License). --}}
@font-face { font-family: "Carlito"; font-style: normal; font-weight: normal; src: url("{{ strtr(resource_path('views/pdf/fonts'), '\\', '/') }}/Carlito-Regular.ttf") format("truetype"); }
@font-face { font-family: "Carlito"; font-style: normal; font-weight: bold; src: url("{{ strtr(resource_path('views/pdf/fonts'), '\\', '/') }}/Carlito-Bold.ttf") format("truetype"); }
